mapper.select:
SELECT id,application_id,owner_principal,candidate_json,candidate_hash,preview_json,
 base_version,base_content_hash,base_presentation_hash,impact_json,to_char(expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') expires_at,
 expires_at >statement_timestamp() unexpired FROM auth_governance.catalog_release_preview WHERE id=#{id}
